suspend fun awaitRateLimit() {
    val limiter = rateLimiter ?: return
    while (true) {
        throwIfCancelled()
        val retryAfterMs = limiter.tryAcquire()
        if (retryAfterMs <= 0L) return
        delay(retryAfterMs.coerceAtMost(CANCELLATION_POLL_INTERVAL_MS))
    }
}
